from typing import List

def rolling_max(numbers: List[int]) -> List[int]:
    max_val = numbers[0]
    res = [0] * len(numbers)

    res[0] = max_val

    for i in range(1, len(numbers)):
        if numbers[i] > max_val:
            max_val = numbers[i]
        res[i] = max_val

    return res

